import{_ as d,o as a,c as e,a2 as s}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"服务表面图","description":"","frontmatter":{},"headers":[],"relativePath":"zh/l1/surface-map.md","filePath":"zh/l1/surface-map.md"}'),o={name:"zh/l1/surface-map.md"};function r(c,t,n,l,i,p){return a(),e("div",null,[...t[0]||(t[0]=[s(`<h1 id="服务表面图" tabindex="-1">服务表面图 <a class="header-anchor" href="#服务表面图" aria-label="Permalink to &quot;服务表面图&quot;">​</a></h1><p>每个 L1SVC 类别、它代理什么、包装它的应用。编号契约是 <code>ocos/interface/l1svc_ops.h</code>（从 <code>ocos/services/sysapi/interface/svc_sysapi_l1svc.h</code> 镜像而来； 上游只允许追加式重编号，然后重新生成）。</p><h2 id="类别" tabindex="-1">类别 <a class="header-anchor" href="#类别" aria-label="Permalink to &quot;类别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Cat</th><th>名称</th><th>代理</th><th>大应用归属</th></tr></thead><tbody><tr><td>1</td><td>time</td><td>RTC / HPET / PM 定时器 / TSC 状态</td><td>hwinfo</td></tr><tr><td>2</td><td>block</td><td>磁盘：状态、分区、mkfs、fsck、A/B 工具、测试</td><td>disk-tool</td></tr><tr><td>3</td><td>nic</td><td>网卡家族 + 无线（wifi/bt）</td><td>net-tool</td></tr><tr><td>4</td><td>snd</td><td>音频设备、音量、play、按驱动测试</td><td>sound-tool</td></tr><tr><td>5</td><td>power</td><td>shutdown/reboot/halt/sleep + 路径测试</td><td>power</td></tr><tr><td>6</td><td>ota（selfhost）</td><td>更新链、checkupdate、配置存储、A/B</td><td>update</td></tr><tr><td>7</td><td>fs</td><td>mount/umount/fatmount/fatstat/tree</td><td>disk-tool、files</td></tr><tr><td>8</td><td>net</td><td>ip/dhcp/dns/arp/route/firewall/ssh/sshd</td><td>net-tool</td></tr><tr><td>9</td><td>health</td><td>快照 / 导出 / 监视</td><td>sysdiag</td></tr><tr><td>10</td><td>klog</td><td>dmesg / logcat / logctl</td><td>sysdiag</td></tr><tr><td>11</td><td>watchdog</td><td>看门狗命令家族</td><td>sysdiag</td></tr><tr><td>12</td><td>crypto</td><td>cryptotest / dhtest</td><td>（仅经典）</td></tr><tr><td>13</td><td>l1</td><td>注册表列表本身（help -a/-w）、l1test、ldd</td><td>-</td></tr><tr><td>14</td><td>display</td><td>uname/stats/lang/font/encoding/IME 操作</td><td>hwinfo</td></tr><tr><td>15</td><td>input</td><td>touchpad / touchtest</td><td>hwinfo</td></tr><tr><td>16</td><td>camera</td><td>uvc/scsi/gameport/parallel/ir + 测试</td><td>hwinfo</td></tr><tr><td>17</td><td>usb</td><td>usb status/dev + usb 测试家族</td><td>hwinfo</td></tr><tr><td>18</td><td>ocire</td><td>启动卷日志环（仅守卫操作）</td><td>-</td></tr><tr><td>19</td><td>diag</td><td>内存/调度器/vm 测试、PCI/ACPI/I2C/SMBus、crash</td><td>sysdiag</td></tr><tr><td>20</td><td>tui</td><td>桌面 + TUI 命令家族</td><td>（tui 应用）</td></tr></tbody></table><h2 id="l1svc-之外-直接系统调用" tabindex="-1">L1SVC 之外：直接系统调用 <a class="header-anchor" href="#l1svc-之外-直接系统调用" aria-label="Permalink to &quot;L1SVC 之外：直接系统调用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>系统调用</th><th>使用者</th></tr></thead><tbody><tr><td><code>SYS_OPEN/READ/WRITE/CLOSE/STAT/READDIR</code></td><td>文件工具（cat、cp、ls、...）</td></tr><tr><td><code>SYS_FORK/EXECVE/WAIT4</code></td><td>ush、run、files - 程序启动器模式</td></tr><tr><td><code>SYS_PIPE/DUP/DUP2</code></td><td>ush 管道与重定向</td></tr><tr><td><code>SYS_READLINE</code>（73）</td><td>向导行输入（回显 + 退格，阻塞）</td></tr><tr><td><code>SYS_GETCH</code>（74）</td><td>非阻塞单键（菜单、编辑器）</td></tr><tr><td><code>SYS_NETCMD</code>（101）</td><td>ping / wget / ifconfig / netstat 桥</td></tr><tr><td><code>SYS_PS</code>（102）</td><td>ps / top 进程表</td></tr></tbody></table><p>完整的 x86_64 系统调用表注册在 <code>ocos/services/sysapi/src/svc_sysapi_syscall.c</code>。</p><h2 id="输出契约" tabindex="-1">输出契约 <a class="header-anchor" href="#输出契约" aria-label="Permalink to &quot;输出契约&quot;">​</a></h2><p>服务操作通过调用者的缓冲返回<strong>英文 ASCII 文本</strong> - 这些行是 面向脚本的契约，也是向导探针：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;IP: 10.0.2.15&quot;            (net ip)</span></span>
<span class="line"><span>&quot;DHCP success: IP=...&quot;     (net dhcp)</span></span>
<span class="line"><span>&quot;A/B disk: present&quot;        (ota update status)</span></span>
<span class="line"><span>&quot;New version available.&quot;   (ota checkupdate)</span></span>
<span class="line"><span>&quot;Current version is up to date.&quot;</span></span>
<span class="line"><span>&quot;reboot required&quot;          (ota update, after install)</span></span></code></pre></div><p>重命名其中任何一行都是破坏性变更：向导（<code>wizard_lib.h</code> 的 <code>wiz_find</code>）、E2E 套件和用户文档都在读它们。</p><h2 id="help-a-help-w" tabindex="-1">help -a / help -w <a class="header-anchor" href="#help-a-help-w" aria-label="Permalink to &quot;help -a / help -w&quot;">​</a></h2><p>注册表列表（L1SVC cat &quot;l1&quot; op 1）为每个程序渲染名字 + wp 标签</p><ul><li>双语提示。<code>help -w</code> 按标签分组；<code>mega</code> 组（8 个合并应用）排在 视图最前，其后是 18 个历史服务组。</li></ul>`,14)])])}const f=d(o,[["render",r]]);export{u as __pageData,f as default};
